/* ══════════════════════════════════════════
   INDEXED DB PERSISTENT STORAGE
   ══════════════════════════════════════════ */
const DB_NAME = 'SmartBoardDB_v3';
const DB_STORE = 'board_data';
let dbInstancePromise = null;

function openDB() {
  if (typeof window === 'undefined' || !window.indexedDB) return Promise.resolve(null);
  if (!dbInstancePromise) {
    dbInstancePromise = new Promise((resolve) => {
      const req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains(DB_STORE)) {
          db.createObjectStore(DB_STORE);
        }
      };
      req.onsuccess = () => {
        const db = req.result;
        db.onclose = () => { dbInstancePromise = null; };
        db.onerror = () => { dbInstancePromise = null; };
        resolve(db);
      };
      req.onerror = () => {
        dbInstancePromise = null;
        resolve(null);
      };
    });
  }
  return dbInstancePromise;
}

async function saveToDB(key, value) {
  try {
    const db = await openDB();
    if (!db) return;
    const tx = db.transaction(DB_STORE, 'readwrite');
    tx.objectStore(DB_STORE).put(value, key);
  } catch (err) {
    console.warn('IndexedDB save warning:', err);
  }
}

async function getFromDB(key) {
  try {
    const db = await openDB();
    if (!db) return null;
    return new Promise((resolve) => {
      const tx = db.transaction(DB_STORE, 'readonly');
      const req = tx.objectStore(DB_STORE).get(key);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (err) {
    return null;
  }
}

async function removeFromDB(key) {
  try {
    const db = await openDB();
    if (!db) return;
    const tx = db.transaction(DB_STORE, 'readwrite');
    tx.objectStore(DB_STORE).delete(key);
  } catch (err) {}
}

/* ══════════════════════════════════════════
   FIREBASE SERIAL & LICENSE SYSTEM (Modular Integration)
   ══════════════════════════════════════════ */
let isAppFullyActivated = false;

function showActivationModalWithError(errMsg) {
  isAppFullyActivated = false;
  setAppFullyActivated(false);
  document.body.classList.add('app-locked-unlicensed');
  const actCurtain = document.getElementById('license-security-curtain');
  if (actCurtain) actCurtain.style.display = 'flex';

  const actModal = document.getElementById('activation-modal');
  const actStatusEl = document.getElementById('about-license-status');
  const errEl = document.getElementById('activation-error-msg');
  const errText = document.getElementById('activation-error-text');
  const statusTxt = document.getElementById('activation-status-text');
  const btnCancelAct = document.getElementById('btn-cancel-activation');

  if (actStatusEl) actStatusEl.innerText = 'بانتظار التفعيل';
  if (statusTxt) statusTxt.innerText = '';
  if (errEl) {
    if (errText) errText.innerText = errMsg;
    else errEl.innerText = errMsg;
    errEl.classList.remove('hidden');
  }
  if (btnCancelAct) btnCancelAct.classList.add('hidden');

  if (actModal) {
    actModal.style.display = 'flex';
    actModal.style.opacity = '1';
    actModal.style.pointerEvents = 'auto';
    if (window.lucide && window.lucide.createIcons) window.lucide.createIcons();
  }
}

async function checkAndInitActivation() {
  const actModal = document.getElementById('activation-modal');
  const actCurtain = document.getElementById('license-security-curtain');
  const actStatusEl = document.getElementById('about-license-status');
  const statusTxt = document.getElementById('activation-status-text');
  const errEl = document.getElementById('activation-error-msg');
  const errText = document.getElementById('activation-error-text');
  const btnAct = document.getElementById('btn-activate-now');
  const btnActText = document.getElementById('btn-activate-text');
  const keyInp = document.getElementById('activation-key-input');
  const btnOpenAct = document.getElementById('btn-open-activation');
  const btnCurtainExit = document.getElementById('btn-curtain-exit');
  const btnExitModal = document.getElementById('btn-exit-modal');
  const btnReopenAct = document.getElementById('btn-reopen-activation');
  const btnPaste = document.getElementById('btn-paste-key');
  const btnCancelAct = document.getElementById('btn-cancel-activation');
  const keyValidIcon = document.getElementById('activation-key-valid-icon');

  // 1. تحقق محلي فوري موثق من التخزين المشفر
  const cache = await getLocalActivationCache(getFromDB, removeFromDB, saveToDB);
  if (cache && cache.activated) {
    isAppFullyActivated = true;
    setAppFullyActivated(true);
    document.body.classList.remove('app-locked-unlicensed');
    if (actCurtain) actCurtain.style.display = 'none';
    if (actModal) {
      actModal.style.display = 'none';
      actModal.style.pointerEvents = 'none';
    }
    if (actStatusEl) actStatusEl.innerText = 'مُفعّل بالكامل ✔️';

    // Show welcome modal if not seen before
    try {
      if (!localStorage.getItem('wb3_seen')) {
        const wm = document.getElementById('welcome-modal');
        if (wm) {
          wm.classList.remove('hidden');
          wm.style.display = 'flex';
          wm.style.opacity = '1';
        }
      }
    } catch (e) {}

    // Start silent background heartbeat to re-verify server status and grace period
    startLicenseHeartbeat({
      onRevoked: (errMsg) => {
        isAppFullyActivated = false;
        setAppFullyActivated(false);
        showActivationModalWithError(errMsg);
      },
      saveToDB,
      removeFromDB
    });
  } else {
    // 2. إذا لم يكن مفعلاً، يتم تفعيل القفل وحظر الكانفاس وإظهار نافذة إدخال المفتاح
    isAppFullyActivated = false;
    setAppFullyActivated(false);
    document.body.classList.add('app-locked-unlicensed');
    if (actCurtain) actCurtain.style.display = 'flex';
    if (actModal) {
      actModal.style.display = 'flex';
      actModal.style.opacity = '1';
      actModal.style.pointerEvents = 'auto';
      if (window.lucide && window.lucide.createIcons) window.lucide.createIcons();
    }
    if (actStatusEl) actStatusEl.innerText = 'بانتظار التفعيل';
    if (btnCancelAct) btnCancelAct.classList.add('hidden');
    const wm = document.getElementById('welcome-modal');
    if (wm) wm.style.display = 'none';
  }

  // ربط زر لصق المفتاح من الحافظة مع معالجة قيود الأمان في المتصفح وتطبيقات سطح المكتب
  if (btnPaste && !btnPaste._bound) {
    btnPaste._bound = true;
    btnPaste.addEventListener('click', async () => {
      let text = '';

      // 1. التركيز على النافذة لتجاوز خطأ "Document is not focused" في المتصفحات
      try { window.focus(); } catch (e) {}

      // 2. محاولة القراءة من واجهة Tauri الأصلية لسطح المكتب
      try {
        if (window.__TAURI__ && window.__TAURI__.clipboard && window.__TAURI__.clipboard.readText) {
          text = await window.__TAURI__.clipboard.readText();
        }
      } catch (e) {
        console.warn('Tauri clipboard read failed:', e);
      }

      // 3. محاولة القراءة من واجهة الحافظة القياسية للمتصفح (Navigator Clipboard API)
      if (!text && navigator.clipboard && navigator.clipboard.readText) {
        try {
          text = await navigator.clipboard.readText();
        } catch (err) {
          console.warn('Navigator clipboard readText blocked or permission denied:', err);
        }
      }

      // 4. محاولة بديلة عبر execCommand إذا كان مدعوماً
      if (!text && keyInp) {
        try {
          keyInp.focus();
          document.execCommand('paste');
          if (keyInp.value) text = keyInp.value;
        } catch (e) {}
      }

      // 5. في حال حظر المتصفح قراءة الحافظة داخل الـ iframe أمنياً، فتح نافذة إدخال فورية
      if (!text && keyInp) {
        try {
          const userPrompt = window.prompt('الصق رمز التفعيل هنا (Ctrl + V):', keyInp.value || '');
          if (userPrompt) text = userPrompt;
        } catch (e) {}
      }

      // 6. استخراج وتنسيق المفتاح إذا تم الحصول عليه
      if (text && keyInp) {
        const match = text.match(/WB-[A-Z0-9]{4}-[A-Z0-9]{4}-[A-Z0-9]{4}/i);
        if (match) {
          keyInp.value = match[0].toUpperCase();
        } else {
          keyInp.value = text.trim().toUpperCase().replace(/[^A-Z0-9-]/g, '');
        }
        keyInp.dispatchEvent(new Event('input'));
        keyInp.focus();

        // إظهار تأكيد بصري بنجاح اللصق
        const originalHTML = btnPaste.innerHTML;
        btnPaste.innerHTML = `<i data-lucide="check" class="w-3.5 h-3.5 text-blue-600"></i><span class="text-blue-600 font-bold">تم اللصق ✔️</span>`;
        if (window.lucide && window.lucide.createIcons) window.lucide.createIcons();
        setTimeout(() => {
          btnPaste.innerHTML = originalHTML;
          if (window.lucide && window.lucide.createIcons) window.lucide.createIcons();
        }, 1800);
      } else if (keyInp) {
        keyInp.focus();
        keyInp.select();
        const originalHTML = btnPaste.innerHTML;
        btnPaste.innerHTML = `<span class="text-blue-600 font-bold">اضغط Ctrl + V</span>`;
        setTimeout(() => {
          btnPaste.innerHTML = originalHTML;
          if (window.lucide && window.lucide.createIcons) window.lucide.createIcons();
        }, 2200);
      }
    });
  }

  // دعم حدث اللصق المباشر داخل حقل الإدخال لاستخراج الرمز النظيف تلقائياً
  if (keyInp && !keyInp._pasteBound) {
    keyInp._pasteBound = true;
    keyInp.addEventListener('paste', (e) => {
      const pasted = (e.clipboardData || window.clipboardData)?.getData('text');
      if (pasted) {
        const match = pasted.match(/WB-[A-Z0-9]{4}-[A-Z0-9]{4}-[A-Z0-9]{4}/i);
        if (match) {
          e.preventDefault();
          keyInp.value = match[0].toUpperCase();
          keyInp.dispatchEvent(new Event('input'));
        }
      }
    });
  }

  // تنسيق المفتاح التلقائي وإظهار شارة الصلاحية
  if (keyInp && !keyInp._formatBound) {
    keyInp._formatBound = true;
    keyInp.addEventListener('input', () => {
      let val = keyInp.value.toUpperCase().replace(/[^A-Z0-9-]/g, '');
      keyInp.value = val;
      if (keyValidIcon) {
        if (val.length >= 10) keyValidIcon.classList.remove('hidden');
        else keyValidIcon.classList.add('hidden');
      }
      if (errEl) errEl.classList.add('hidden');
    });
  }

  // ربط زر الرجوع إلى السبورة (يتاح فقط إذا كانت السبورة مفعّلة مسبقاً)
  if (btnCancelAct && !btnCancelAct._bound) {
    btnCancelAct._bound = true;
    btnCancelAct.addEventListener('click', () => {
      if (isAppFullyActivated && actModal) {
        actModal.style.opacity = '0';
        actModal.style.pointerEvents = 'none';
        setTimeout(() => { actModal.style.display = 'none'; }, 300);
      }
    });
  }

  // ربط زر إغلاق البرنامج في النافذة
  if (btnExitModal && !btnExitModal._bound) {
    btnExitModal._bound = true;
    btnExitModal.addEventListener('click', () => {
      exitApplication();
    });
  }

  // ربط أزرار الستار الأمني
  if (btnCurtainExit && !btnCurtainExit._bound) {
    btnCurtainExit._bound = true;
    btnCurtainExit.addEventListener('click', () => {
      exitApplication();
    });
  }
  if (btnReopenAct && !btnReopenAct._bound) {
    btnReopenAct._bound = true;
    btnReopenAct.addEventListener('click', () => {
      if (actModal) {
        actModal.style.display = 'flex';
        actModal.style.opacity = '1';
        actModal.style.pointerEvents = 'auto';
        if (window.lucide && window.lucide.createIcons) window.lucide.createIcons();
      }
      if (keyInp) keyInp.focus();
    });
  }

  // ربط زر فتح نافذة التفعيل من "حول التطبيق"
  if (btnOpenAct && !btnOpenAct._bound) {
    btnOpenAct._bound = true;
    btnOpenAct.addEventListener('click', () => {
      const aboutM = document.getElementById('about-modal');
      if (aboutM) aboutM.style.display = 'none';
      if (btnCancelAct) {
        if (isAppFullyActivated) btnCancelAct.classList.remove('hidden');
        else btnCancelAct.classList.add('hidden');
      }
      if (actModal) {
        actModal.style.display = 'flex';
        actModal.style.opacity = '1';
        actModal.style.pointerEvents = 'auto';
        if (window.lucide && window.lucide.createIcons) window.lucide.createIcons();
      }
      if (keyInp) keyInp.focus();
    });
  }

  // 3. ربط حدث زر التفعيل
  if (btnAct && keyInp && !btnAct._actBound) {
    btnAct._actBound = true;
    btnAct.addEventListener('click', async () => {
      const inputVal = keyInp.value.trim().toUpperCase();
      if (!inputVal) {
        if (errEl) {
          if (errText) errText.innerText = 'يرجى إدخال رمز التفعيل أولاً';
          else errEl.innerText = 'يرجى إدخال رمز التفعيل أولاً';
          errEl.classList.remove('hidden');
        }
        keyInp.focus();
        return;
      }

      if (errEl) errEl.classList.add('hidden');
      if (statusTxt) {
        statusTxt.innerText = 'جاري التحقق من الرمز والاتصال...';
        statusTxt.className = 'text-xs font-semibold transition-all text-blue-600 dark:text-blue-400 animate-pulse';
      }
      btnAct.disabled = true;
      if (btnActText) btnActText.innerText = 'جاري التحقق...';

      const result = await verifyAndActivateSerial(inputVal, '', saveToDB);

      btnAct.disabled = false;
      if (btnActText) btnActText.innerText = 'تفعيل ومتابعة';

      if (result.success) {
        isAppFullyActivated = true;
        setAppFullyActivated(true);
        document.body.classList.remove('app-locked-unlicensed');
        if (actCurtain) actCurtain.style.display = 'none';
        if (statusTxt) {
          statusTxt.innerText = 'تم التفعيل بنجاح ✔️';
          statusTxt.className = 'text-xs font-semibold text-blue-600 dark:text-blue-400';
        }
        if (actStatusEl) actStatusEl.innerText = 'مُفعّل بالكامل ✔️';
        startLicenseHeartbeat({
          onRevoked: (errMsg) => {
            isAppFullyActivated = false;
            setAppFullyActivated(false);
            showActivationModalWithError(errMsg);
          },
          saveToDB,
          removeFromDB
        });
        setTimeout(() => {
          if (actModal) {
            actModal.style.opacity = '0';
            actModal.style.pointerEvents = 'none';
            setTimeout(() => { actModal.style.display = 'none'; }, 300);
          }
          try {
            if (!localStorage.getItem('wb3_seen')) {
              const wm = document.getElementById('welcome-modal');
              if (wm) {
                wm.classList.remove('hidden');
                wm.style.display = 'flex';
                wm.style.opacity = '1';
              }
            }
          } catch (e) {}
        }, 1100);
      } else {
        if (statusTxt) statusTxt.innerText = '';
        if (errEl) {
          if (errText) errText.innerText = result.msg;
          else errEl.innerText = result.msg;
          errEl.classList.remove('hidden');
        }
      }
    });

    keyInp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        btnAct.click();
      }
    });
  }
}


/* ══════════════════════════════════════════
   WELCOME MODAL & HELPERS
   ══════════════════════════════════════════ */
window.hideWM = function (e) {
  if (e && e.cancelable) e.preventDefault();
  const m = document.getElementById('welcome-modal');
  if (m) {
    m.style.opacity = '0';
    m.style.pointerEvents = 'none';
    setTimeout(() => {
      m.style.display = 'none';
      try { localStorage.setItem('wb3_seen', '1'); } catch (x) {}
    }, 300);
  }
};

(function () {
  try {
    if (localStorage.getItem('wb3_seen')) {
      const m = document.getElementById('welcome-modal');
      if (m) {
        m.style.display = 'none';
        m.style.pointerEvents = 'none';
      }
    }
  } catch (x) {}
})();

function showToast(msg, duration = 2500) {
  const el = document.getElementById('toast-msg');
  if (!el) return;
  el.textContent = msg;
  el.classList.remove('opacity-0', 'translate-y-4');
  el.classList.add('opacity-100', 'translate-y-0', 'toast-enter');
  clearTimeout(el._t);
  el._t = setTimeout(() => {
    el.classList.remove('opacity-100', 'translate-y-0', 'toast-enter');
    el.classList.add('opacity-0', 'translate-y-4');
  }, duration);
}

function refreshIcons(container = document) {
  try {
    createIcons({ icons, nameAttr: 'data-lucide', root: container });
  } catch (e) {}
}

