          bodyHoloGradEnd: isHolo ? '#001a4d' : (isStudio ? '#f1f5f9' : '#082f49'),
          bodyHoloFill: isHolo ? 'url(#' + uid + '_bodyHoloGrad)' : (isStudio ? '#f8fafc' : '#020617'),
