        return `<svg width="100%" height="100%" viewBox="0 0 ${svgW} ${svgH}" xmlns="http://www.w3.org/2000/svg" style="overflow:visible; display:block;">
          <defs>
            <marker id="arr-r-res-${safeColorId}" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="6" markerHeight="6" orient="auto">
              <path d="M 0 1 L 10 5 L 0 9 z" fill="${color}" />
            </marker>
          </defs>
          <line x1="20" y1="${cy}" x2="${endX}" y2="${cy}" stroke="${color}" stroke-width="4" stroke-dasharray="6 3" marker-end="url(#arr-r-res-${safeColorId})" />
          <path d="M ${endX - 12} ${cy - 6} L ${endX - 4} ${cy} L ${endX - 12} ${cy + 6}" stroke="${color}" stroke-width="3" fill="none" />
          <text x="${svgW / 2}" y="${cy - 12}" fill="${color}" font-size="14" font-weight="bold" font-family="sans-serif" text-anchor="middle" dir="ltr">${label} = ${val} ${unit}</text>
        </svg>`;
