        const wallDef = createGlossyGradientDefs(color, uid, { name: 'wall', type: 'linear', x1: '0%', y1: '0%', x2: '100%', y2: '100%' });
        const vacDef = createGlossyGradientDefs('#38bdf8', uid, { name: 'vac', lightenPct: 35, darkenPct: -25 });
