'biology.digestive-interactive': {
      type: 'biology.digestive-interactive',
      category: 'biology',
      name: 'الجهاز الهضمي (تفاعلي)',
      schemaVersion: 1,
      propSchema: [
        { id: 'theme', type: 'select', label: 'نمط العرض', options: [{val: 'colored', label: 'ملون (قياسي)'}, {val: 'outline', label: 'مخطط شفاف (اختبار)'}] },
        { id: 'labelsMode', type: 'select', label: 'وضع التأشيرات', options: [{val: 'hover', label: 'عند التمرير'}, {val: 'always', label: 'إظهار دائم'}, {val: 'hidden', label: 'إخفاء للتقويم'}] }
      ],
      defaultProps: { theme: 'colored', labelsMode: 'hover' },
      defaultSize: { w: 300, h: 500 },
      renderSVG: (props, w, h) => {
        const theme = props.theme || 'colored';
        const labelsMode = props.labelsMode || 'hover';
        const isOutline = theme === 'outline';
        
        const labelsOpacity = labelsMode === 'always' ? '1 !important' : (labelsMode === 'hidden' ? '0 !important' : '0');
        const labelsPointer = labelsMode === 'always' ? 'auto' : 'none';

        // Organ colors
        const liverFill = isOutline ? '#f8fafc' : '#991b1b';
        const stomachFill = isOutline ? '#f8fafc' : '#f87171';
        const pancFill = isOutline ? '#f8fafc' : '#fbbf24';
        const largeIntStroke = isOutline ? '#cbd5e1' : '#d97706';
        const smallIntStroke = isOutline ? '#94a3b8' : '#f472b6';
        const outlineStroke = isOutline ? '#64748b' : 'none';

        return `<svg width="100%" height="100%" viewBox="0 0 300 500" xmlns="http://www.w3.org/2000/svg" style="overflow:visible;">
  <style>
    .organ { cursor: pointer; transition: all 0.3s; }
    .organ:hover { filter: drop-shadow(0 0 8px rgba(0,0,0,0.3)) brightness(1.1); transform: scale(1.02); }
    .label { opacity: ${labelsOpacity}; transition: opacity 0.3s; pointer-events: ${labelsPointer}; }
    ${labelsMode === 'hover' ? '.organ:hover + .label { opacity: 1; }' : ''}
  </style>
  <defs>
    <filter id="shadowD"><feDropShadow dx="2" dy="2" stdDeviation="2" flood-opacity="0.2"/></filter>
  </defs>

  <rect x="0" y="0" width="300" height="500" fill="#fff" rx="15"/>
  
  <!-- Silhouette -->
  <path d="M 100 50 C 100 20, 140 10, 150 10 C 170 10, 180 30, 180 60 C 180 80, 170 90, 160 100 L 160 130 C 190 140, 230 160, 240 200 L 240 500 L 60 500 L 60 200 C 70 160, 110 140, 140 130 L 140 100 C 120 90, 100 70, 100 50 Z" fill="#f1f5f9" stroke="#cbd5e1" stroke-width="2"/>

  <!-- Mouth & Salivary Glands -->
  <g class="organ" transform="origin(140 70)">
    <ellipse cx="140" cy="70" rx="15" ry="8" fill="${isOutline ? '#f8fafc' : '#fca5a5'}" stroke="${outlineStroke}"/>
    <circle cx="160" cy="65" r="5" fill="${isOutline ? '#e2e8f0' : '#38bdf8'}"/>
    <circle cx="165" cy="80" r="6" fill="${isOutline ? '#e2e8f0' : '#38bdf8'}"/>
  </g>
  <g class="label">
    <rect x="170" y="55" width="120" height="40" rx="5" fill="#1e293b" opacity="0.9"/>
    <text x="230" y="70" fill="#fff" font-family="Cairo, sans-serif" font-size="10" font-weight="bold" text-anchor="middle">الفم والغدد اللعابية</text>
    <text x="230" y="85" fill="#67e8f9" font-family="Cairo, sans-serif" font-size="10" text-anchor="middle">إنزيم الأميلاز اللعابي</text>
  </g>

  <!-- Esophagus -->
  <g class="organ">
    <rect x="145" y="80" width="10" height="100" fill="${isOutline ? '#f8fafc' : '#fca5a5'}" stroke="${outlineStroke}" filter="url(#shadowD)"/>
  </g>
  <g class="label">
    <rect x="180" y="120" width="60" height="25" rx="5" fill="#1e293b" opacity="0.9"/>
    <text x="210" y="137" fill="#fff" font-family="Cairo, sans-serif" font-size="12" font-weight="bold" text-anchor="middle">المريء</text>
  </g>

  <!-- Liver -->
  <g class="organ" transform="origin(110 210)">
    <path d="M 150 180 C 180 180, 190 200, 180 230 C 150 210, 100 240, 80 220 C 70 200, 100 180, 150 180 Z" fill="${liverFill}" stroke="${outlineStroke}" filter="url(#shadowD)"/>
    <circle cx="130" cy="225" r="8" fill="${isOutline ? '#e2e8f0' : '#22c55e'}"/> 
  </g>
  <g class="label">
    <rect x="5" y="180" width="110" height="40" rx="5" fill="#1e293b" opacity="0.9"/>
    <text x="60" y="195" fill="#fff" font-family="Cairo, sans-serif" font-size="10" font-weight="bold" text-anchor="middle">الكبد والحويصل</text>
    <text x="60" y="210" fill="#86efac" font-family="Cairo, sans-serif" font-size="10" text-anchor="middle">العصارة الصفراوية</text>
  </g>

  <!-- Stomach -->
  <g class="organ" transform="origin(170 220)">
    <path d="M 145 180 C 145 200, 120 220, 140 240 C 160 260, 200 260, 200 220 C 200 180, 155 180, 145 180 Z" fill="${stomachFill}" stroke="${outlineStroke}" filter="url(#shadowD)"/>
  </g>
  <g class="label">
    <rect x="180" y="190" width="115" height="40" rx="5" fill="#1e293b" opacity="0.9"/>
    <text x="237" y="205" fill="#fff" font-family="Cairo, sans-serif" font-size="10" font-weight="bold" text-anchor="middle">المعدة (غدد معدية)</text>
    <text x="237" y="220" fill="#fca5a5" font-family="Cairo, sans-serif" font-size="10" text-anchor="middle">بروتياز 1 (بيپسين)</text>
  </g>

  <!-- Pancreas -->
  <g class="organ" transform="origin(160 250)">
    <path d="M 130 240 Q 160 235 190 250 Q 160 260 130 250 Z" fill="${pancFill}" stroke="${outlineStroke}" filter="url(#shadowD)"/>
  </g>
  <g class="label">
    <rect x="195" y="250" width="100" height="40" rx="5" fill="#1e293b" opacity="0.9"/>
    <text x="245" y="265" fill="#fff" font-family="Cairo, sans-serif" font-size="10" font-weight="bold" text-anchor="middle">البنكرياس</text>
    <text x="245" y="280" fill="#fde047" font-family="Cairo, sans-serif" font-size="10" text-anchor="middle">عصارة بنكرياسية</text>
  </g>

  <!-- Large Intestine -->
  <g class="organ">
    <path d="M 100 350 L 100 280 L 200 280 L 200 380 L 150 380 L 150 420" fill="none" stroke="${largeIntStroke}" stroke-width="20" stroke-linejoin="round" stroke-linecap="round" filter="url(#shadowD)"/>
  </g>
  <g class="label">
    <rect x="10" y="320" width="80" height="25" rx="5" fill="#1e293b" opacity="0.9"/>
    <text x="50" y="337" fill="#fff" font-family="Cairo, sans-serif" font-size="12" font-weight="bold" text-anchor="middle">المعي الغليظ</text>
  </g>

  <!-- Small Intestine -->
  <g class="organ">
    <path d="M 140 250 Q 110 270 120 300 Q 140 330 160 300 Q 180 270 170 330 Q 150 360 130 340 Q 110 320 180 350" fill="none" stroke="${smallIntStroke}" stroke-width="12" stroke-linecap="round" stroke-linejoin="round" filter="url(#shadowD)"/>
  </g>
  <g class="label">
    <rect x="90" y="380" width="130" height="40" rx="5" fill="#1e293b" opacity="0.9"/>
    <text x="155" y="395" fill="#fff" font-family="Cairo, sans-serif" font-size="10" font-weight="bold" text-anchor="middle">المعي الدقيق</text>
    <text x="155" y="410" fill="#fbcfe8" font-family="Cairo, sans-serif" font-size="10" text-anchor="middle">الامتصاص + غدد معوية</text>
  </g>
  
  <text x="150" y="20" fill="#64748b" font-family="Cairo, sans-serif" font-size="12" text-anchor="middle" dir="rtl">مرر الفأرة فوق الأعضاء</text>
</svg>`;
      }
    },
