  function setupFlyoutSearch() {
    document.querySelectorAll('.flyout-search-input').forEach(input => {
      input.addEventListener('input', (e) => {
        const query = e.target.value.trim().toLowerCase();
        const subject = input.dataset.subject;
        let dropdown = physDropdown;
        if (subject === 'teacher') dropdown = teacherDropdown;
        else if (subject === 'chem') dropdown = chemDropdown;
        else if (subject === 'biology') dropdown = bioDropdown;
        else if (subject === 'geography') dropdown = geoDropdown;
        else if (subject === 'astronomy') dropdown = astroDropdown;
        else if (subject === 'shapes3d') dropdown = shapes3dDropdown;
        if (!dropdown) return;

        const categories = dropdown.querySelectorAll('.category-group');
        const quickContainer = dropdown.querySelector('[id$="-quick-container"]');
        if (!query) {
          categories.forEach(cat => {
            cat.classList.remove('hidden');
            const content = cat.querySelector('.category-content');
            const toggle = cat.querySelector('.category-toggle-btn');
            if (content) content.classList.add('hidden');
            if (toggle) toggle.setAttribute('aria-expanded', 'false');
            const chevron = cat.querySelector('.chevron-icon');
            if (chevron) chevron.classList.remove('rotate-180');
          });
          if (quickContainer) quickContainer.classList.remove('hidden');
          dropdown.querySelectorAll('.edu-add-btn').forEach(btn => btn.classList.remove('hidden'));
          return;
        }
        if (quickContainer) quickContainer.classList.add('hidden');
        categories.forEach(cat => {
          const btns = cat.querySelectorAll('.edu-add-btn');
          let hasMatch = false;
          btns.forEach(btn => {
            const title = (btn.getAttribute('title') || '').toLowerCase();
            const text = (btn.textContent || '').toLowerCase();
            const type = (btn.dataset.eduType || '').toLowerCase();
            if (title.includes(query) || text.includes(query) || type.includes(query)) {
              btn.classList.remove('hidden');
              hasMatch = true;
            } else {
              btn.classList.add('hidden');
            }
          });
          if (hasMatch) {
            cat.classList.remove('hidden');
            const content = cat.querySelector('.category-content');
            const toggle = cat.querySelector('.category-toggle-btn');
            if (content) content.classList.remove('hidden');
            if (toggle) toggle.setAttribute('aria-expanded', 'true');
            const chevron = cat.querySelector('.chevron-icon');
            if (chevron) chevron.classList.add('rotate-180');
          } else {
            cat.classList.add('hidden');
          }
        });
        const mainBtn = subject === 'teacher' ? mainTeacherBtn : (subject === 'chem' ? mainChemBtn : (subject === 'biology' ? mainBioBtn : (subject === 'geography' ? mainGeoBtn : (subject === 'astronomy' ? mainAstroBtn : (subject === 'shapes3d' ? mainShapes3dBtn : mainPhysBtn)))));
        if (mainBtn) positionFlyout(mainBtn, dropdown);
      });
    });
  }

  function setupAccordionToggles() {
    document.querySelectorAll('.category-toggle-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const catGroup = btn.closest('.category-group');
        if (!catGroup) return;
        const content = catGroup.querySelector('.category-content');
        const chevron = catGroup.querySelector('.chevron-icon');
        if (!content) return;
        const isHidden = content.classList.contains('hidden');
        if (isHidden) {
          content.classList.remove('hidden');
          content.classList.add('flex');
          btn.setAttribute('aria-expanded', 'true');
          if (chevron) chevron.classList.add('rotate-180');
        } else {
          content.classList.add('hidden');
          content.classList.remove('flex');
          btn.setAttribute('aria-expanded', 'false');
          if (chevron) chevron.classList.remove('rotate-180');
        }
        const dropdown = btn.closest('#teacher-dropdown') || btn.closest('#physics-dropdown') || btn.closest('#chem-dropdown') || btn.closest('#bio-dropdown') || btn.closest('#geo-dropdown') || btn.closest('#astro-dropdown') || btn.closest('#shapes3d-dropdown');
        const mainBtn = dropdown ? (dropdown.id === 'teacher-dropdown' ? mainTeacherBtn : (dropdown.id === 'chem-dropdown' ? mainChemBtn : (dropdown.id === 'bio-dropdown' ? mainBioBtn : (dropdown.id === 'geo-dropdown' ? mainGeoBtn : (dropdown.id === 'astro-dropdown' ? mainAstroBtn : (dropdown.id === 'shapes3d-dropdown' ? mainShapes3dBtn : mainPhysBtn)))))) : null;
        if (dropdown && mainBtn) {
          positionFlyout(mainBtn, dropdown);
        }
      });
    });
  }

  document.addEventListener('click', (e) => {
    const starBtn = e.target.closest('.fav-star-btn');
    if (starBtn) {
      e.stopPropagation();
      e.preventDefault();
      const type = starBtn.dataset.eduType;
      toggleFavorite(type);
      return;
    }
    const addBtn = e.target.closest('.edu-add-btn');
    if (addBtn) {
      e.stopPropagation();
      const type = addBtn.dataset.eduType;
      if (type) {
        createEduObject(type, WW / 2, WH / 2);
        addRecentTool(type);
        if (teacherDropdown) { teacherDropdown.classList.add('hidden'); teacherDropdown.classList.remove('flex'); }
        if (physDropdown) { physDropdown.classList.add('hidden'); physDropdown.classList.remove('flex'); }
        if (chemDropdown) { chemDropdown.classList.add('hidden'); chemDropdown.classList.remove('flex'); }
        if (bioDropdown) { bioDropdown.classList.add('hidden'); bioDropdown.classList.remove('flex'); }
        if (geoDropdown) { geoDropdown.classList.add('hidden'); geoDropdown.classList.remove('flex'); }
        if (astroDropdown) { astroDropdown.classList.add('hidden'); astroDropdown.classList.remove('flex'); }
        if (shapes3dDropdown) { shapes3dDropdown.classList.add('hidden'); shapes3dDropdown.classList.remove('flex'); }
      }
    }
  });
  updateFavoritesUI();
  updateRecentsUI();
  setupAccordionToggles();
  setupFlyoutSearch();

  const tbc = document.getElementById('toolbar-content');
  if (tbc) {
    tbc.addEventListener('click', (e) => {
      let tb = e.target.closest('.tool-btn');
      if (tb) {
        const isMainPen = tb.id === 'main-pen-btn';
        const isDropdownItem = tb.closest('#pen-dropdown');
        const dropdown = document.getElementById('pen-dropdown');
        if (isMainPen) {
          // Handled directly by mainPenBtn.onclick
          return;
        } else if (dropdown) {
          dropdown.classList.add('hidden');
          dropdown.classList.remove('flex');
        }
        if (isDropdownItem) {
          const mainBtn = document.getElementById('main-pen-btn');
          const mainIcon = document.getElementById('main-pen-icon');
          const mainText = document.getElementById('main-pen-text');
          if (mainBtn && mainIcon && mainText) {
            mainBtn.dataset.tool = tb.dataset.tool;
            mainText.innerText = tb.dataset.text;
            const newIcon = document.createElement('i');
            newIcon.className = 'w-5 h-5';
            newIcon.setAttribute('data-lucide', tb.dataset.icon);
            newIcon.id = 'main-pen-icon';
            mainIcon.parentNode.replaceChild(newIcon, mainIcon);
            refreshIcons(mainBtn);
          }
          tb = mainBtn;
        }
        if (S.tool === 'select' && tb.dataset.tool !== 'select') commitSel();
        S.tool = tb.dataset.tool;
        updateToolbarActive(S.tool);
        if (typeof setStrokeWidth === 'function') {
          setStrokeWidth(S.tool === 'eraser' ? S.eraserWidth : S.strokeWidth);
        } else {
          const sl = document.getElementById('sw-range');
          const sv = document.getElementById('sw-val');
          if (sl && sv) {
            if (S.tool === 'eraser') {
              sl.value = S.eraserWidth;
              sv.innerText = S.eraserWidth;
            } else {
              sl.value = S.strokeWidth;
              sv.innerText = S.strokeWidth;
            }
          }
        }
        if (ctn) {
          if (S.tool === 'select') ctn.classList.add('tool-select');
          else ctn.classList.remove('tool-select');
        }
        setAppCursor(S.tool === 'pan' ? 'grab' : S.tool === 'text' || S.tool === 'math' ? 'text' : S.tool === 'select' ? 'default' : S.tool === 'eraser' ? 'none' : 'crosshair');
        if (ecur) ecur.style.display = S.tool === 'eraser' ? 'block' : 'none';

        const radDiv = document.getElementById('radius-ctrl-div');
        if (radDiv) {
          radDiv.style.display = S.tool === 'brush' ? 'block' : 'none';
        }
        return;
      }
    });
  }

  function selectColor(color) {
    if (!color) return;
    S.color = color;
    const target = color.toLowerCase();
    let hasPresetMatch = false;

    document.querySelectorAll('.color-btn').forEach((b) => {
      const c = (b.dataset.color || '').toLowerCase();
      const isMatch = c === target;
      if (isMatch) hasPresetMatch = true;
      b.classList.toggle('active-color', isMatch);
      b.setAttribute('data-active', isMatch ? 'true' : 'false');
    });

    const customBtn = document.getElementById('custom-color-btn');
    const customPicker = document.getElementById('custom-color-picker');

    if (customPicker && customPicker.value.toLowerCase() !== target) {
      customPicker.value = color;
    }

    if (customBtn) {
      const isCustomActive = !hasPresetMatch;
      customBtn.classList.toggle('active-color', isCustomActive);
      customBtn.setAttribute('data-active', isCustomActive ? 'true' : 'false');
    }
  }

  function setStrokeWidth(width, updateRange = true) {
    const v = Math.max(1, Math.min(50, parseInt(width, 10) || 3));
    if (S.tool === 'eraser') {
      S.eraserWidth = v;
    } else {
      S.strokeWidth = v;
    }

    const swVal = document.getElementById('sw-val');
    if (swVal) swVal.innerText = v;

    const swRange = document.getElementById('sw-range');
    if (swRange && updateRange) swRange.value = v;

    const qv = document.getElementById('pen-quick-sw-val');
    if (qv) qv.innerText = `${v}px`;

    document.querySelectorAll('.pen-width-preset').forEach((btn) => {
      const w = parseInt(btn.dataset.width, 10);
      btn.classList.toggle('active', w === v);
    });

    if (S.tool === 'eraser') {
      updateEraserCursor();
    }
  }

  // Circular Color Picker Events
  const cp = document.getElementById('color-picker');
  if (cp) {
    cp.addEventListener('click', (e) => {
      const cb = e.target.closest('.color-btn');
      if (cb && cb.dataset.color) {
        selectColor(cb.dataset.color);
      }
    });
  }

  const customColorPicker = document.getElementById('custom-color-picker');
  if (customColorPicker) {
    customColorPicker.addEventListener('input', (e) => {
      selectColor(e.target.value);
    });
  }

  const radiusIn = document.getElementById('radius-range');
