  // ══════════════════════════════════════════ 
  // APPLICATION VERSION & STORE UPDATES LOGIC 
  // ══════════════════════════════════════════ 
  const APP_CURRENT_VERSION = '7.0.1.0';
  const STORE_PRODUCT_ID = '9PFL6KSV2V57'; 
  const STORE_DEEP_LINK = 'ms-windows-store://pdp/?productid=9PFL6KSV2V57'; 
  const STORE_WEB_URL = 'https://apps.microsoft.com/detail/9PFL6KSV2V57'; 
  const REMOTE_VERSION_MANIFEST_URL = '/version.json'; 
  
  function parseAppVersion(vStr) { 
    if (!vStr || typeof vStr !== 'string') return [0, 0, 0, 0]; 
    const parts = vStr.replace(/^[^\d]*/, '').split('.').map(n => parseInt(n, 10) || 0); 
    while (parts.length < 4) parts.push(0); 
    return parts.slice(0, 4); 
  } 
  
  function compareAppVersions(v1, v2) { 
    const p1 = parseAppVersion(v1); 
    const p2 = parseAppVersion(v2); 
    for (let i = 0; i < 4; i++) { 
      if (p1[i] > p2[i]) return 1; 
      if (p1[i] < p2[i]) return -1; 
    } 
    return 0; 
  } 
  
  function showUpdateNotificationModal(updateData) { 
    const updateModal = document.getElementById('update-modal'); 
    if (!updateModal) return; 
    const curEl = document.getElementById('update-modal-cur-ver'); 
    const newEl = document.getElementById('update-modal-new-ver'); 
    const clEl = document.getElementById('update-modal-changelog'); 
    if (curEl) curEl.textContent = APP_CURRENT_VERSION; 
    if (newEl) newEl.textContent = updateData.version || 'Unknown'; 
    if (clEl && Array.isArray(updateData.changelog) && updateData.changelog.length > 0) { 
      clEl.innerHTML = updateData.changelog.map(item => `<li>${escapeXml(item)}</li>`).join(''); 
    } 
    updateModal.classList.remove('hidden'); 
    updateModal.classList.add('flex'); 
    refreshIcons(updateModal); 
  } 
  
  async function checkAppUpdates(isManual = false) { 
    const statusBadge = document.getElementById('update-check-status-badge'); 
    const btnCheck = document.getElementById('btn-check-updates'); 
    if (statusBadge && isManual) { 
      statusBadge.textContent = 'Checking...'; 
    } 
    if (btnCheck && isManual) { 
      btnCheck.disabled = true; 
      btnCheck.classList.add('opacity-70'); 
    } 
    try { 
      const res = await fetch(`${REMOTE_VERSION_MANIFEST_URL}?_t=${Date.now()}`, { cache: 'no-store' }); 
      if (!res.ok) throw new Error('Failed to fetch update manifest'); 
      const data = await res.json(); 
      const latestVer = data.version || APP_CURRENT_VERSION; 
      const hasUpdate = compareAppVersions(latestVer, APP_CURRENT_VERSION) > 0; 
      if (hasUpdate) { 
        if (statusBadge) { 
          statusBadge.innerHTML = `<span class="text-amber-600 dark:text-amber-400 font-bold">Update Available ${escapeXml(latestVer)}</span>`;
        }
        showUpdateNotificationModal(data);
      } else {
        if (statusBadge) {
          statusBadge.innerHTML = `<span class="text-emerald-600 dark:text-emerald-400 font-bold">Latest Version (${APP_CURRENT_VERSION}) ✓</span>`;
        }
        if (isManual) {
          showToast(`You are using the latest version (${APP_CURRENT_VERSION}) ✓`, 3000);
        }
      }
    } catch (err) {
      console.warn('Update check info:', err);
      if (statusBadge) {
        statusBadge.textContent = 'Unable to connect to server';
      }
      if (isManual) {
        showToast('Unable to check for updates automatically. Please check the Microsoft Store.', 3500);
      }
    } finally {
      if (btnCheck && isManual) {
        btnCheck.disabled = false;
        btnCheck.classList.remove('opacity-70');
      }
    }
  }

  // About Modal
  const aboutModal = document.getElementById('about-modal');
